int sum_digits(int n)
{
    // base case: zero ka sum zero hai
    if (n == 0)
    {
        return 0;
    }

    // last digit nikaalo
    int last_digit = n % 10;

    // baaki recursion khud kar lega
    return last_digit + sum_digits(n);
}
